import React, { useState, useMemo, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, LabelList } from 'recharts';
import { Filter, Search, UserX, Info } from 'lucide-react';
import { ChartContainer, FilterChip } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';
import { useTranslation } from '../context/LanguageContext';

interface SubjectAnalysisViewProps {
  selectedPeriod: string;
  periodData: any[];
  subjects: string[];
  classes: string[];
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>;
  thresholds: Record<string, number>;
  thresholdType: 'rank' | 'percent';
  totalStudents: number;
  // External control props
  overrideSubject?: string;
  overrideClasses?: string[];
  hideControls?: boolean;
}

const SubjectAnalysisView: React.FC<SubjectAnalysisViewProps> = ({
  selectedPeriod, periodData, subjects, classes, allSubjectRanks, thresholds, thresholdType, totalStudents,
  overrideSubject, overrideClasses, hideControls = false
}) => {
  const { t } = useTranslation();
  const [internalSelectedSubject, setInternalSelectedSubject] = useState(subjects[0] || '');
  const [internalSelectedClasses, setInternalSelectedClasses] = useState<string[]>([classes[0]]);

  // Use override props if provided, otherwise internal state
  const selectedSubject = overrideSubject !== undefined ? overrideSubject : internalSelectedSubject;
  const selectedClasses = overrideClasses !== undefined ? overrideClasses : internalSelectedClasses;

  // Initialize internal state if override is provided (optional, for sync)
  useEffect(() => {
    if (overrideSubject) setInternalSelectedSubject(overrideSubject);
  }, [overrideSubject]);

  useEffect(() => {
    if (overrideClasses) setInternalSelectedClasses(overrideClasses);
  }, [overrideClasses]);

  // 在单科分析页中，teKongLimit 是用于确定“重点关注名单”的阈值
  const teKongThresholdValue = useMemo(() => {
    return thresholds['特控'] || 0;
  }, [thresholds]);

  const distributionData = useMemo(() => 
    AnalysisEngine.getSubjectDistribution(
      selectedPeriod, selectedSubject, selectedClasses, periodData, allSubjectRanks, thresholds, thresholdType, totalStudents
    ),
    [selectedPeriod, selectedSubject, selectedClasses, periodData, allSubjectRanks, thresholds, thresholdType, totalStudents]
  );

  const belowLineStudents = useMemo(() => 
    AnalysisEngine.getBelowLineStudents(
      selectedPeriod, selectedSubject, selectedClasses, periodData, allSubjectRanks, teKongThresholdValue, thresholdType
    ),
    [selectedPeriod, selectedSubject, selectedClasses, periodData, allSubjectRanks, teKongThresholdValue, thresholdType]
  );

  const toggleClass = (cls: string) => {
    if (hideControls) return;
    setInternalSelectedClasses(prev => 
      prev.includes(cls) ? prev.filter(p => p !== cls) : [...prev, cls]
    );
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
      {!hideControls && (
        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6 no-print">
          <div className="space-y-3 flex-1">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Search className="w-3 h-3" /> {t('subject.select_subject')}
            </p>
            <div className="flex flex-wrap gap-2">
              {subjects.map(sub => (
                <FilterChip 
                  key={sub}
                  label={sub}
                  active={selectedSubject === sub}
                  onClick={() => setInternalSelectedSubject(sub)}
                  color="indigo"
                />
              ))}
            </div>
          </div>

          <div className="space-y-3 flex-1">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Filter className="w-3 h-3" /> {t('subject.select_classes')}
            </p>
            <div className="flex flex-wrap gap-2">
              {classes.map(cls => (
                <FilterChip 
                  key={cls}
                  label={cls}
                  active={selectedClasses.includes(cls)}
                  onClick={() => toggleClass(cls)}
                  color="blue"
                />
              ))}
            </div>
          </div>
        </div>
      )}

      <div className="print-break-inside-avoid">
        <ChartContainer title={t('subject.dist_title').replace('{subject}', selectedSubject).replace('{period}', selectedPeriod)}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={distributionData} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} />
              <YAxis stroke="#94a3b8" fontSize={12} />
              <Tooltip 
                cursor={{ fill: '#f8fafc' }}
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                formatter={(value: number) => [`${value} ${t('common.participants')}`, t('common.participants')]}
              />
              <Bar dataKey="count" radius={[6, 6, 0, 0]} barSize={50}>
                {distributionData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
                <LabelList dataKey="count" position="top" style={{ fill: '#64748b', fontSize: '12px', fontWeight: 'bold' }} />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </ChartContainer>
      </div>

      <div className="bg-white rounded-3xl border border-rose-100 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500 print-break-inside-avoid">
        <div className="px-8 py-6 bg-rose-50/50 border-b border-rose-100 flex items-center justify-between">
          <div>
            <h3 className="text-xs font-bold text-rose-600 uppercase tracking-widest flex items-center gap-2">
              <UserX className="w-4 h-4" /> {t('subject.focus_list')}
            </h3>
            <p className="text-[10px] text-rose-400 mt-1">
              {t('subject.focus_desc')
                .replace('{classes}', selectedClasses.join(', '))
                .replace('{subject}', selectedSubject)
                .replace('{count}', String(belowLineStudents.length))
              }
            </p>
          </div>
        </div>
        <div className="p-8">
          {belowLineStudents.length > 0 ? (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {belowLineStudents.map((s, idx) => (
                <div 
                  key={idx}
                  className="bg-white border border-rose-100 rounded-xl p-3 flex flex-col gap-1 hover:shadow-md transition-all hover:scale-[1.02]"
                >
                  <span className="text-sm font-bold text-gray-800">{s.name}</span>
                  <div className="flex items-center justify-between text-[10px]">
                    <span className="text-gray-400">{s.class}</span>
                    <span className="text-rose-600 font-black">#{s.rank}</span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-10 text-gray-400 italic">
              <Info className="w-8 h-8 mb-2 opacity-20 text-green-500" />
              <p className="text-sm">{t('subject.no_below_line')}</p>
            </div>
          )}
        </div>
      </div>

      <div className="bg-blue-50/50 p-6 rounded-2xl border border-blue-100 print-break-inside-avoid">
        <h4 className="text-xs font-bold text-blue-900 uppercase tracking-widest mb-3">{t('subject.insight_title')}</h4>
        <p className="text-sm text-blue-800 leading-relaxed">
          {t('subject.insight_desc').replace('{subject}', selectedSubject).replace('{period}', selectedPeriod)}
        </p>
      </div>
    </div>
  );
};

export default SubjectAnalysisView;

import React, { useState, useMemo, useEffect } from 'react';
import { Filter, ArrowUpDown, TrendingUp, TrendingDown, Search, Calculator, Calendar, Flame, Target } from 'lucide-react';
import { StudentRecord } from '../types';
import { SelectInput, SearchInput, FilterChip } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';
import { useTranslation } from '../context/LanguageContext';

interface ProgressAnalysisViewProps {
  students: StudentRecord[];
  allPeriods: string[];
  allHistoricalRanks: Record<string, Record<string, number>>;
  classes: string[];
  // External control props
  overridePeriodX?: string;
  overridePeriodY?: string;
  overrideClasses?: string[];
  hideControls?: boolean;
}

const ProgressAnalysisView: React.FC<ProgressAnalysisViewProps> = ({
  students, allPeriods, allHistoricalRanks, classes,
  overridePeriodX, overridePeriodY, overrideClasses, hideControls = false
}) => {
  const { t } = useTranslation();
  const [activeSubTab, setActiveSubTab] = useState<'coefficient' | 'streak'>('coefficient');

  const [internalPeriodX, setInternalPeriodX] = useState<string>(allPeriods[allPeriods.length - 2] || allPeriods[0] || '');
  const [internalPeriodY, setInternalPeriodY] = useState<string>(allPeriods[allPeriods.length - 1] || '');
  const [internalSelectedClasses, setInternalSelectedClasses] = useState<string[]>(classes);

  // Use override props if provided
  const periodX = overridePeriodX !== undefined ? overridePeriodX : internalPeriodX;
  const periodY = overridePeriodY !== undefined ? overridePeriodY : internalPeriodY;
  const selectedClasses = overrideClasses !== undefined ? overrideClasses : internalSelectedClasses;

  // Sync internal state if overrides provided (optional)
  useEffect(() => { if (overridePeriodX) setInternalPeriodX(overridePeriodX); }, [overridePeriodX]);
  useEffect(() => { if (overridePeriodY) setInternalPeriodY(overridePeriodY); }, [overridePeriodY]);
  useEffect(() => { if (overrideClasses) setInternalSelectedClasses(overrideClasses); }, [overrideClasses]);

  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' }>({
    key: 'coefficient',
    direction: 'desc'
  });

  const coefficientData = useMemo(() => {
    const rawData = AnalysisEngine.getProgressAnalysisData(students, periodX, periodY, allHistoricalRanks);
    return rawData.filter(d => 
      selectedClasses.includes(d.class) && 
      d.name.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [students, periodX, periodY, allHistoricalRanks, selectedClasses, searchTerm]);

  const streakData = useMemo(() => {
    return students
      .filter(s => selectedClasses.includes(s.class) && s.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .map(student => {
        const info = AnalysisEngine.calculateRangeStreakInfo(student, allHistoricalRanks, allPeriods, periodX, periodY);
        const ranksX = allHistoricalRanks[periodX] || {};
        const ranksY = allHistoricalRanks[periodY] || {};

        return {
          name: student.name,
          class: student.class,
          rankX: ranksX[student.name] || '-',
          rankY: ranksY[student.name] || '-',
          rankChange: info.totalChange,
          streakCount: info.count,
          type: info.type
        };
      })
      .filter(d => d.rankX !== '-' && d.rankY !== '-');
  }, [students, periodX, periodY, allHistoricalRanks, allPeriods, selectedClasses, searchTerm]);

  const currentData = activeSubTab === 'coefficient' ? coefficientData : streakData;

  const sortedData = useMemo(() => {
    return [...currentData].sort((a: any, b: any) => {
      // Handle the rank columns which might be strings/numbers
      const valA = a[sortConfig.key];
      const valB = b[sortConfig.key];

      if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [currentData, sortConfig]);

  const toggleSort = (key: string) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'desc' ? 'asc' : 'desc'
    }));
  };

  const toggleClass = (cls: string) => {
    if (hideControls) return;
    setInternalSelectedClasses(prev => 
      prev.includes(cls) ? prev.filter(p => p !== cls) : [...prev, cls]
    );
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
      {!hideControls && (
        <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm space-y-6 no-print">
          <div className="flex flex-col md:flex-row gap-6">
            <div className="flex-1 space-y-3">
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                <Calendar className="w-3 h-3" /> {t('progress.period_select')}
              </h4>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <p className="text-[10px] text-gray-400 font-bold ml-1">{t('progress.period_x')}</p>
                  <SelectInput 
                    value={periodX}
                    onChange={(e) => setInternalPeriodX(e.target.value)}
                  >
                    {allPeriods.map(p => <option key={p} value={p}>{p}</option>)}
                  </SelectInput>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] text-gray-400 font-bold ml-1">{t('progress.period_y')}</p>
                  <SelectInput 
                    value={periodY}
                    onChange={(e) => setInternalPeriodY(e.target.value)}
                  >
                    {allPeriods.map(p => <option key={p} value={p}>{p}</option>)}
                  </SelectInput>
                </div>
              </div>
            </div>
            <div className="flex-1 space-y-3">
               <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                <Filter className="w-3 h-3" /> {t('progress.class_filter')}
              </h4>
              <div className="flex flex-wrap gap-2">
                {classes.map(cls => (
                  <FilterChip 
                    key={cls}
                    label={cls}
                    active={selectedClasses.includes(cls)}
                    onClick={() => toggleClass(cls)}
                    color="blue"
                  />
                ))}
              </div>
            </div>
          </div>

          <div className="pt-4 border-t border-gray-50 flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex bg-gray-100 p-1.5 rounded-xl self-start">
              <button 
                onClick={() => { setActiveSubTab('coefficient'); setSortConfig({ key: 'coefficient', direction: 'desc' }); }}
                className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${activeSubTab === 'coefficient' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
              >
                <Target className="w-3.5 h-3.5" />
                {t('progress.subtab_coefficient')}
              </button>
              <button 
                onClick={() => { setActiveSubTab('streak'); setSortConfig({ key: 'streakCount', direction: 'desc' }); }}
                className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${activeSubTab === 'streak' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
              >
                <Flame className="w-3.5 h-3.5" />
                {t('progress.subtab_streak')}
              </button>
            </div>

            <div className="flex-1 w-full md:w-auto flex flex-col md:flex-row items-center gap-4">
              <SearchInput 
                 className="w-full md:flex-1"
                 placeholder={t('common.search')}
                 value={searchTerm}
                 onChange={setSearchTerm}
              />
              {activeSubTab === 'coefficient' && (
                <div className="shrink-0 flex items-center gap-2 text-xs font-bold text-gray-400 bg-blue-50 px-3 py-1.5 rounded-lg border border-blue-100">
                  <Calculator className="w-3 h-3 text-blue-600" />
                  {t('progress.coefficient_formula')}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden print-break-inside-avoid">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className={`${activeSubTab === 'coefficient' ? 'bg-gray-900' : 'bg-indigo-900'} text-white`}>
              <tr>
                <th className="px-6 py-5 cursor-pointer transition-colors" onClick={() => toggleSort('name')}>
                  <div className="flex items-center gap-2">{t('progress.table_name')} <ArrowUpDown className="w-3 h-3 opacity-50" /></div>
                </th>
                <th className="px-6 py-5 text-center cursor-pointer transition-colors" onClick={() => toggleSort('rankX')}>
                  <div className="flex items-center justify-center gap-2">{t('progress.table_rank_x').replace('{period}', periodX || '')} <ArrowUpDown className="w-3 h-3 opacity-50" /></div>
                </th>
                <th className="px-6 py-5 text-center cursor-pointer transition-colors" onClick={() => toggleSort('rankY')}>
                  <div className="flex items-center justify-center gap-2">{t('progress.table_rank_x').replace('{period}', periodY || '')} <ArrowUpDown className="w-3 h-3 opacity-50" /></div>
                </th>
                <th className="px-6 py-5 text-center cursor-pointer transition-colors" onClick={() => toggleSort('rankChange')}>
                  <div className="flex items-center justify-center gap-2">{t('progress.table_rank_change')} <ArrowUpDown className="w-3 h-3 opacity-50" /></div>
                </th>
                {activeSubTab === 'coefficient' ? (
                  <th className="px-6 py-5 text-center cursor-pointer transition-colors" onClick={() => toggleSort('coefficient')}>
                    <div className="flex items-center justify-center gap-2">{t('progress.table_coefficient')} <ArrowUpDown className="w-3 h-3 opacity-50" /></div>
                  </th>
                ) : (
                  <th className="px-6 py-5 text-center cursor-pointer transition-colors" onClick={() => toggleSort('streakCount')}>
                    <div className="flex items-center justify-center gap-2">{t('progress.table_streak')} <ArrowUpDown className="w-3 h-3 opacity-50" /></div>
                  </th>
                )}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {sortedData.map((row: any, idx) => (
                <tr key={idx} className="hover:bg-blue-50/30 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-bold text-gray-900">{row.name}</div>
                    <div className="text-[10px] text-gray-400 font-bold uppercase">{row.class}</div>
                  </td>
                  <td className="px-6 py-4 text-center text-gray-600 font-medium">#{row.rankX}</td>
                  <td className="px-6 py-4 text-center text-gray-600 font-medium">#{row.rankY}</td>
                  <td className={`px-6 py-4 text-center font-black ${row.rankChange > 0 ? 'text-emerald-600' : row.rankChange < 0 ? 'text-rose-600' : 'text-gray-400'}`}>
                    <div className="flex items-center justify-center gap-1">
                      {row.rankChange > 0 ? <TrendingUp className="w-3 h-3" /> : row.rankChange < 0 ? <TrendingDown className="w-3 h-3" /> : null}
                      {row.rankChange > 0 ? `+${row.rankChange}` : row.rankChange === 0 ? '-' : row.rankChange}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    {activeSubTab === 'coefficient' ? (
                      <span className={`inline-block px-3 py-1 rounded-full text-xs font-black ${row.coefficient > 0 ? 'bg-emerald-100 text-emerald-700' : row.coefficient < 0 ? 'bg-rose-100 text-rose-700' : 'bg-gray-100 text-gray-500'}`}>
                        {row.coefficient > 0 ? `+${row.coefficient.toFixed(2)}` : row.coefficient.toFixed(2)}
                      </span>
                    ) : (
                      <div className="flex items-center justify-center gap-2">
                        {row.streakCount > 0 ? (
                          <span className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-black ${row.type === 'improvement' ? 'bg-amber-100 text-amber-700' : 'bg-rose-100 text-rose-700'}`}>
                            <Flame className={`w-3.5 h-3.5 ${row.type === 'improvement' ? 'text-amber-500' : 'text-rose-500'}`} />
                            {row.type === 'improvement' 
                              ? t('progress.table_streak_up').replace('{count}', String(row.streakCount))
                              : t('progress.table_streak_down').replace('{count}', String(row.streakCount))}
                          </span>
                        ) : (
                          <span className="text-gray-300 text-xs">-</span>
                        )}
                      </div>
                    )}
                  </td>
                </tr>
              ))}
              {sortedData.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-6 py-20 text-center text-gray-400 italic">
                    {t('progress.no_data')}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {!hideControls && (
        <div className="bg-blue-50/50 p-6 rounded-2xl border border-blue-100 animate-in fade-in slide-in-from-top-2 no-print">
          <h4 className="text-xs font-black text-blue-900 uppercase tracking-widest mb-3 flex items-center gap-2">
            <TrendingUp className="w-4 h-4" /> 
            {activeSubTab === 'coefficient' ? '分析逻辑：点对点对比' : '分析逻辑：区间趋势分析'}
          </h4>
          <p className="text-sm text-blue-800 leading-relaxed">
            {activeSubTab === 'coefficient' 
              ? `当前模式仅对比 ${periodX} 与 ${periodY} 两次考试的名次变动。系数越接近 ±2.0，说明变动幅度相对于初始位次越剧烈。`
              : `当前模式分析从 ${periodX} 到 ${periodY} 期间，学生是否保持了连续的进步或退步。名次变动反映了该考试区间内的净增量。`
            }
          </p>
        </div>
      )}
    </div>
  );
};

