                allHistoricalRanks={allHistoricalRanks}
                classes={data.classes}
                // External Control
                overridePeriodX={modules.progress.periodX}
                overridePeriodY={modules.progress.periodY}
                overrideClasses={modules.progress.classes}
                hideControls={true}
              />
            </section>
          )}

          {/* 7. Student Detail (Class List) Section */}
          {modules.student.enabled && (
            <section className="print-break-inside-avoid">
              <div className="flex items-center gap-3 mb-6 pb-2 border-b border-gray-100">
