          <p className="text-center text-[10px] font-bold text-gray-400 uppercase tracking-widest">
            {t('export.report_footer')} • {new Date().getFullYear()}
          </p>
        </div>
      </div>
    </div>
  );
};

export default ExportView;

import React, { useState, useMemo, useEffect } from 'react';
import { AnalysisState } from '../types';
import { SelectInput, FilterChip, StatCard } from './SharedComponents';
import { Calendar, Filter, Printer, FileSpreadsheet, Layers, PieChart as PieIcon, BarChart2, CheckSquare, Square, GraduationCap, History, Crown, Calculator, TrendingUp, Target, ChevronDown, ChevronUp } from 'lucide-react';
import { useTranslation } from '../context/LanguageContext';
import * as AnalysisEngine from '../utils/analysisUtils';

// Import Views
import SchoolView from './SchoolView';
import ClassComparisonView from './ClassComparisonView';
import EliteBenchmarksView from './EliteBenchmarksView';
import ExamParametersView from './ExamParametersView';
import SubjectAnalysisView from './SubjectAnalysisView';
import ProgressAnalysisView from './ProgressAnalysisView';

interface ExportViewProps {
  data: AnalysisState;
}

const ExportView: React.FC<ExportViewProps> = ({ data }) => {
  const { t } = useTranslation();
  const allPeriods = useMemo(() => 
    data.students[0]?.history.map(h => h.period) || [], 
    [data.students]
  );

  // --- Global State ---
  const [globalPeriod, setGlobalPeriod] = useState<string>(allPeriods[allPeriods.length - 1] || '');

  // --- Module Configuration State ---
  const [modules, setModules] = useState({
    school: { enabled: true },
    comparison: { enabled: true, classes: [...data.classes], thresholds: data.settings?.comparisonThresholds || [50, 100, 200] },
    kings: { enabled: false, benchmarkClass: data.classes[0] },
    parameters: { enabled: false },
    subject: { enabled: false, subject: data.subjects[0] || '', classes: [...data.classes] },
    progress: { enabled: false, periodX: allPeriods[0] || '', periodY: allPeriods[allPeriods.length - 1] || '', classes: [...data.classes] },
    student: { enabled: true, class: data.classes[0] }
  });

  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    school: false,
    comparison: true,
    kings: true,
    parameters: false,
    subject: true,
    progress: true,
    student: true
  });

  // --- Derived Data for Global Context (reused across some views) ---
  const allHistoricalRanks = useMemo(() => 
    AnalysisEngine.calculateHistoricalRanks(data.students), 
    [data.students]
  );

  const periodData = useMemo(() => 
    AnalysisEngine.getPeriodSnapshot(data.students, globalPeriod, allHistoricalRanks),
    [data.students, globalPeriod, allHistoricalRanks]
  );

  // --- Helpers for Configuration Updates ---
  const toggleModule = (key: keyof typeof modules) => {
    setModules(prev => ({ ...prev, [key]: { ...prev[key], enabled: !prev[key].enabled } }));
  };

  const updateModuleConfig = (key: keyof typeof modules, updates: any) => {
    setModules(prev => ({ ...prev, [key]: { ...prev[key], ...updates } }));
  };

  const toggleExpanded = (key: string) => {
    setExpandedSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Data Prep for Specific Views (Lifted Logic) ---

  // 1. School View Data
  const admissionLabels = [
    { key: '清北', color: '#be123c' },
    { key: 'C9', color: '#1e40af' },
    { key: '高分数', color: '#0369a1' },
    { key: '名校', color: '#0d9488' },
    { key: '特控', color: '#10b981' },
  ];
  const hasImportedStatus = useMemo(() => 
    periodData.some(s => s.currentStatus !== undefined && s.currentStatus !== ''),
    [periodData]
  );
  // We use local state for thresholds in SchoolView, but for export we just use global/defaults for now or could add config
  const [manualThresholds, setManualThresholds] = useState(data.settings?.manualThresholds || { '清北': 5, 'C9': 30, '高分数': 100, '名校': 300, '特控': 600 });
  const [thresholdType, setThresholdType] = useState<'rank' | 'percent'>(data.settings?.thresholdType || 'rank');
  const effectiveThresholdType = hasImportedStatus ? 'percent' : thresholdType;
  const effectiveThresholds = useMemo(() => {
     if (hasImportedStatus) return AnalysisEngine.deriveThresholdsFromMetadata(periodData, admissionLabels);
     return manualThresholds;
  }, [hasImportedStatus, periodData, manualThresholds]);

  // 2. Class Comparison Data
  const classComparisonData = useMemo(() => data.subjects.map(sub => {
    const entry: any = { name: sub };
    modules.comparison.classes.forEach(cls => {
      const clsStudents = periodData.filter(s => s.class === cls);
      entry[cls] = clsStudents.length > 0 ? parseFloat((clsStudents.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / clsStudents.length).toFixed(2)) : 0;
    });
    return entry;
  }), [periodData, data.subjects, modules.comparison.classes]);

  const rankingDistributionData = useMemo(() => 
    modules.comparison.thresholds.sort((a: number, b: number) => a - b).map((bucket: number) => {
      const entry: any = { name: `Top ${bucket}`, limit: bucket };
      modules.comparison.classes.forEach(cls => { 
        entry[cls] = periodData.filter(s => s.class === cls && s.periodSchoolRank <= bucket).length; 
      });
      return entry;
    }), [periodData, modules.comparison.classes, modules.comparison.thresholds]);

  const comparisonColors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316'];

  // 3. Elite Benchmarks Data
  const kingsData = useMemo(() => data.subjects.map(sub => ({
    subject: sub,
    classMax: Math.max(...periodData.filter(s => s.class === modules.kings.benchmarkClass).map(s => s.currentScores[sub] || 0), 0),
    gradeMax: Math.max(...periodData.map(s => s.currentScores[sub] || 0), 0)
  })), [periodData, data.subjects, modules.kings.benchmarkClass]);

  const duelData = useMemo(() => {
    const classFirst = periodData.filter(s => s.class === modules.kings.benchmarkClass).sort((a,b) => b.currentTotal - a.currentTotal)[0];
    const schoolFirst = periodData[0];
    return data.subjects.map(sub => ({ subject: sub, classFirst: classFirst?.currentScores[sub] || 0, schoolFirst: schoolFirst?.currentScores[sub] || 0 }));
  }, [periodData, data.subjects, modules.kings.benchmarkClass]);

  // 4. Exam Parameters Data
  const examParameters = useMemo(() => 
    AnalysisEngine.calculateExamParameters(periodData, data.subjects),
    [periodData, data.subjects]
  );

  // 5. Subject Analysis Data - Handled inside component with props
  const allSubjectRanks = useMemo(() => 
    AnalysisEngine.calculateSubjectHistoricalRanks(data.students, data.subjects),
    [data.students, data.subjects]
  );

  // 6. Progress Analysis Data - Handled inside component with props

  // 7. Student Detail (Class List) Data
  const studentListForReport = useMemo(() => {
    return periodData.filter(s => s.class === modules.student.class);
  }, [periodData, modules.student.class]);

  // --- Actions ---

  const handlePrint = () => {
    window.print();
  };

  const handleExportExcel = () => {
    const wb = (window as any).XLSX.utils.book_new();

    // Generate Overview Sheet
    const overviewData = [
      ['Report', 'Exam Analysis Report'],
      ['Period', globalPeriod],
      ['Generated On', new Date().toLocaleString()],
      ['Included Modules', Object.entries(modules).filter(([_, cfg]) => (cfg as any).enabled).map(([k]) => k).join(', ')]
    ];
    const wsOverview = (window as any).XLSX.utils.aoa_to_sheet(overviewData);
    (window as any).XLSX.utils.book_append_sheet(wb, wsOverview, "Overview");

    // We can add logic here to export data for enabled modules
    if (modules.student.enabled) {
      const wsStudents = (window as any).XLSX.utils.json_to_sheet(studentListForReport.map(s => ({
        Rank: s.periodSchoolRank,
        Name: s.name,
        Class: s.class,
        Total: s.currentTotal,
        Status: AnalysisEngine.getAdmissionCategory(s.periodSchoolRank, effectiveThresholds, effectiveThresholdType, periodData.length, s.currentStatus),
        ...s.currentScores
      })));
      (window as any).XLSX.utils.book_append_sheet(wb, wsStudents, `Students - ${modules.student.class}`);
    }

    (window as any).XLSX.writeFile(wb, `Report_${globalPeriod}.xlsx`);
  };

  return (
    <div className="flex flex-col lg:flex-row gap-8 animate-in fade-in duration-500 print:block">
      {/* Sidebar Controls - Hidden on Print */}
      <div className="w-full lg:w-96 space-y-6 no-print shrink-0">
        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm space-y-6 sticky top-24 h-[calc(100vh-8rem)] overflow-y-auto custom-scrollbar">
          <div>
            <h2 className="text-xl font-black text-gray-900 mb-1">{t('export.title')}</h2>
            <p className="text-xs text-gray-500">{t('export.subtitle')}</p>
          </div>

          <div className="space-y-6">
            <div className="space-y-2 bg-blue-50/50 p-4 rounded-xl border border-blue-100">
              <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest flex items-center gap-2">
                <Calendar className="w-3.5 h-3.5" /> {t('export.config_period')} (Global)
              </label>
              <SelectInput value={globalPeriod} onChange={(e) => setGlobalPeriod(e.target.value)}>
                {allPeriods.map(p => <option key={p} value={p}>{p}</option>)}
              </SelectInput>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 mb-3">
                <Layers className="w-3 h-3" /> {t('export.options_title')}
              </label>

              {/* Module: School View */}
              <div className="border border-gray-100 rounded-xl overflow-hidden">
                <button onClick={() => toggleModule('school')} className="w-full flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 transition-colors">
                  <div className="flex items-center gap-3">
                    {modules.school.enabled ? <CheckSquare className="w-4 h-4 text-blue-600" /> : <Square className="w-4 h-4 text-gray-300" />}
                    <span className="text-sm font-bold text-gray-700">{t('tab.school')}</span>
                  </div>
                </button>
              </div>

              {/* Module: Class Comparison */}
              <div className="border border-gray-100 rounded-xl overflow-hidden">
                <div className="flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 transition-colors">
                  <button onClick={() => toggleModule('comparison')} className="flex items-center gap-3">
                    {modules.comparison.enabled ? <CheckSquare className="w-4 h-4 text-blue-600" /> : <Square className="w-4 h-4 text-gray-300" />}
                    <span className="text-sm font-bold text-gray-700">{t('tab.comparison')}</span>
                  </button>
                  <button onClick={() => toggleExpanded('comparison')} className="p-1 hover:bg-gray-200 rounded text-gray-400">
