              {/* Module: Exam Parameters */}
              <div className="border border-gray-100 rounded-xl overflow-hidden">
                <button onClick={() => toggleModule('parameters')} className="w-full flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 transition-colors">
                  <div className="flex items-center gap-3">
                    {modules.parameters.enabled ? <CheckSquare className="w-4 h-4 text-blue-600" /> : <Square className="w-4 h-4 text-gray-300" />}
                    <span className="text-sm font-bold text-gray-700">{t('tab.parameters')}</span>
