                       </div>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-bold text-gray-400 uppercase">{t('common.class')}</p>
                      <div className="flex flex-wrap gap-1.5 max-h-24 overflow-y-auto custom-scrollbar">
                        {data.classes.map(cls => (
                          <FilterChip 
                            key={cls} label={cls} 
                            active={modules.progress.classes.includes(cls)} 
                            onClick={() => {
                              const current = modules.progress.classes;
                              const updated = current.includes(cls) ? current.filter(c => c !== cls) : [...current, cls];
                              updateModuleConfig('progress', { classes: updated });
                            }} 
                            color="blue" className="text-[10px] px-2 py-1"
                          />
                        ))}
                      </div>
                    </div>
                  </div>
                )}
              </div>

               {/* Module: Student Detail (Class List) */}
               <div className="border border-gray-100 rounded-xl overflow-hidden">
                <div className="flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 transition-colors">
                  <button onClick={() => toggleModule('student')} className="flex items-center gap-3">
                    {modules.student.enabled ? <CheckSquare className="w-4 h-4 text-blue-600" /> : <Square className="w-4 h-4 text-gray-300" />}
                    <span className="text-sm font-bold text-gray-700">{t('tab.student')}</span>
                  </button>
                  <button onClick={() => toggleExpanded('student')} className="p-1 hover:bg-gray-200 rounded text-gray-400">
                    {expandedSections.student ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                  </button>
                </div>
                {modules.student.enabled && expandedSections.student && (
                  <div className="p-3 bg-white border-t border-gray-100 space-y-2">
                    <p className="text-[10px] font-bold text-gray-400 uppercase">{t('common.class')}</p>
                    <SelectInput 
                      value={modules.student.class}
                      onChange={(e) => updateModuleConfig('student', { class: e.target.value })}
                      className="py-1.5 text-xs"
                    >
                      {data.classes.map(c => <option key={c} value={c}>{c}</option>)}
                    </SelectInput>
                  </div>
                )}
              </div>

            </div>

            <div className="pt-6 border-t border-gray-100 flex flex-col gap-3">
              <button 
                onClick={handlePrint}
                className="w-full bg-gray-900 text-white py-3 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-gray-800 transition-all shadow-lg"
              >
                <Printer className="w-4 h-4" /> {t('export.btn_print')}
              </button>
              <button 
                onClick={handleExportExcel}
                className="w-full bg-emerald-50 text-emerald-600 border border-emerald-100 py-3 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-emerald-100 transition-all"
              >
                <FileSpreadsheet className="w-4 h-4" /> {t('export.btn_excel')}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Preview Area / Print Area */}
      <div className="flex-1 bg-white min-h-screen lg:rounded-3xl lg:shadow-xl lg:border lg:border-gray-100 print-shadow-none overflow-hidden print:w-full print:block print:overflow-visible print:min-h-0">
        {/* Report Header */}
        <div className="p-8 border-b border-gray-100 flex justify-between items-end bg-gray-50/30 print-break-inside-avoid">
          <div>
            <div className="flex items-center gap-2 text-blue-600 mb-2">
              <GraduationCap className="w-6 h-6" />
              <span className="font-bold text-lg tracking-tight">EduAnalytics Pro</span>
            </div>
            <h1 className="text-3xl font-black text-gray-900">{t('export.preview_header')}</h1>
            <p className="text-gray-500 mt-2 font-medium">{globalPeriod}</p>
          </div>
          <div className="text-right">
            <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mb-1">{t('export.report_generated')}</p>
            <p className="text-sm font-bold text-gray-700">{new Date().toLocaleDateString()}</p>
          </div>
        </div>

        <div className="p-8 space-y-12">

          {/* 1. School View Section */}
          {modules.school.enabled && (
            <section className="print-break-inside-avoid">
              <div className="flex items-center gap-3 mb-6 pb-2 border-b border-gray-100">
                <History className="w-5 h-5 text-gray-400" />
                <h3 className="text-sm font-black text-gray-600 uppercase tracking-widest">{t('tab.school')}</h3>
              </div>
              <SchoolView 
                selectedPeriod={globalPeriod}
                periodData={periodData}
                subjects={data.subjects}
                thresholds={effectiveThresholds}
                setThresholds={setManualThresholds}
                thresholdType={effectiveThresholdType}
                setThresholdType={setThresholdType}
                hasImportedStatus={hasImportedStatus}
                totalStudents={data.students.length}
              />
            </section>
          )}

          {/* 2. Class Comparison Section */}
          {modules.comparison.enabled && (
            <section className="print-break-inside-avoid">
              <div className="flex items-center gap-3 mb-6 pb-2 border-b border-gray-100">
                <Layers className="w-5 h-5 text-gray-400" />
                <h3 className="text-sm font-black text-gray-600 uppercase tracking-widest">{t('tab.comparison')}</h3>
              </div>
              <ClassComparisonView 
                selectedPeriod={globalPeriod}
                classes={data.classes}
                selectedClasses={modules.comparison.classes}
                setSelectedClasses={(val) => {
                   // Only update if array passed, technically view calls setter, we mock it for read-only preview mostly
                   // or map it to config update if we want interactivity inside preview (disabled for consistency)
                }}
                classComparisonData={classComparisonData}
                rankingDistributionData={rankingDistributionData}
                colors={comparisonColors}
                periodData={periodData}
                thresholds={modules.comparison.thresholds}
                setThresholds={(val) => {}} // Read-only in print view
              />
            </section>
          )}

          {/* 3. Elite Benchmarks Section */}
          {modules.kings.enabled && (
            <section className="print-break-inside-avoid">
              <div className="flex items-center gap-3 mb-6 pb-2 border-b border-gray-100">
                <Crown className="w-5 h-5 text-gray-400" />
                <h3 className="text-sm font-black text-gray-600 uppercase tracking-widest">{t('tab.kings')}</h3>
              </div>
              <EliteBenchmarksView 
                selectedPeriod={globalPeriod}
                classes={data.classes}
                benchmarkClass={modules.kings.benchmarkClass}
                setBenchmarkClass={() => {}} // Read-only
                kingsData={kingsData}
                duelData={duelData}
              />
            </section>
          )}

          {/* 4. Exam Parameters Section */}
          {modules.parameters.enabled && (
            <section className="print-break-inside-avoid">
              <div className="flex items-center gap-3 mb-6 pb-2 border-b border-gray-100">
                <Calculator className="w-5 h-5 text-gray-400" />
                <h3 className="text-sm font-black text-gray-600 uppercase tracking-widest">{t('tab.parameters')}</h3>
              </div>
              <ExamParametersView 
                selectedPeriod={globalPeriod}
                examParameters={examParameters}
                colors={comparisonColors}
                totalParticipants={periodData.length}
              />
            </section>
          )}

          {/* 5. Subject Analysis Section */}
          {modules.subject.enabled && (
            <section className="print-break-inside-avoid">
              <div className="flex items-center gap-3 mb-6 pb-2 border-b border-gray-100">
                <BarChart2 className="w-5 h-5 text-gray-400" />
                <h3 className="text-sm font-black text-gray-600 uppercase tracking-widest">{t('tab.subject')}</h3>
              </div>
              <SubjectAnalysisView 
                selectedPeriod={globalPeriod}
                periodData={periodData}
                subjects={data.subjects}
                classes={data.classes}
                allSubjectRanks={allSubjectRanks}
                thresholds={effectiveThresholds}
                thresholdType={effectiveThresholdType}
                totalStudents={data.students.length}
                // External Control
                overrideSubject={modules.subject.subject}
                overrideClasses={modules.subject.classes}
                hideControls={true}
              />
            </section>
          )}

          {/* 6. Progress Analysis Section */}
          {modules.progress.enabled && (
            <section className="print-break-inside-avoid">
               <div className="flex items-center gap-3 mb-6 pb-2 border-b border-gray-100">
                <TrendingUp className="w-5 h-5 text-gray-400" />
                <h3 className="text-sm font-black text-gray-600 uppercase tracking-widest">{t('tab.progress')}</h3>
              </div>
              <ProgressAnalysisView 
                students={data.students}
                allPeriods={allPeriods}
                allHistoricalRanks={allHistoricalRanks}
                classes={data.classes}
                // External Control
                overridePeriodX={modules.progress.periodX}
                overridePeriodY={modules.progress.periodY}
                overrideClasses={modules.progress.classes}
                hideControls={true}
              />
            </section>
          )}

          {/* 7. Student Detail (Class List) Section */}
          {modules.student.enabled && (
            <section className="print-break-inside-avoid">
              <div className="flex items-center gap-3 mb-6 pb-2 border-b border-gray-100">
                <Target className="w-5 h-5 text-gray-400" />
                <h3 className="text-sm font-black text-gray-600 uppercase tracking-widest">{t('tab.student')} - {modules.student.class}</h3>
              </div>
              <div className="border rounded-xl overflow-hidden">
                <table className="w-full text-sm text-left">
                  <thead className="bg-gray-100 text-gray-600 font-bold uppercase text-xs">
                    <tr>
                      <th className="px-6 py-3 w-16">#</th>
                      <th className="px-6 py-3">{t('progress.table_name')}</th>
                      <th className="px-6 py-3 text-center">{t('common.class')}</th>
                      <th className="px-6 py-3 text-right">{t('common.score')}</th>
                      <th className="px-6 py-3 text-center">{t('wizard.admission_status')}</th>
                      {data.subjects.slice(0, 5).map(s => <th key={s} className="px-4 py-3 text-center hidden md:table-cell">{s}</th>)}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {studentListForReport.map((s, idx) => (
                      <tr key={idx} className={idx % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                        <td className="px-6 py-2 font-black text-indigo-600">{s.periodSchoolRank}</td>
                        <td className="px-6 py-2 font-bold text-gray-800">{s.name}</td>
                        <td className="px-6 py-2 text-center text-gray-500 text-xs font-bold uppercase">{s.class}</td>
                        <td className="px-6 py-2 text-right font-bold text-gray-900">{s.currentTotal}</td>
                        <td className="px-6 py-2 text-center">
                          <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded">
                            {AnalysisEngine.getAdmissionCategory(s.periodSchoolRank, effectiveThresholds, effectiveThresholdType, periodData.length, s.currentStatus)}
                          </span>
                        </td>
                        {data.subjects.slice(0, 5).map(sub => (
                           <td key={sub} className="px-4 py-2 text-center text-gray-600 hidden md:table-cell">
                             {s.currentScores[sub] || '-'}
                           </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
          )}

        </div>

        {/* Footer */}
        <div className="p-8 border-t border-gray-100 mt-auto bg-gray-50/50 print:bg-white print:border-none print-break-inside-avoid">
          <p className="text-center text-[10px] font-bold text-gray-400 uppercase tracking-widest">
            {t('export.report_footer')} • {new Date().getFullYear()}
          </p>
        </div>
      </div>
    </div>
  );
};

export default ExportView;
